import RNA, random, math, sys
from multiprocessing import Pool

target = "..((((((((.......(.((((((....)))))).(((((((....))))))).).......))))))))..".strip()
n = len(target)

def struct_to_pairs(s):
    st=[]
    p={}
    for i,c in enumerate(s):
        if c=='(':
            st.append(i)
        elif c==')':
            j=st.pop()
            p[i]=j
            p[j]=i
    return p

target_pairs = struct_to_pairs(target)
bases='ACGU'

def fold(seq):
    fc = RNA.fold_compound(seq)
    mfe, en = fc.mfe()
    return mfe, en

def bpdist(mfe):
    mp = struct_to_pairs(mfe)
    d=0
    allpos = set(target_pairs.keys())|set(mp.keys())
    for i in allpos:
        if target_pairs.get(i) != mp.get(i):
            d+=1
    return d//2

def energy_obj(seq):
    s=''.join(seq)
    mfe, en = fold(s)
    d = bpdist(mfe)
    return d, mfe, en

def init_seq(rng):
    seq=[None]*n
    for i,c in enumerate(target):
        if c=='.':
            seq[i]=rng.choice('AU')
    for i,j in target_pairs.items():
        if i<j:
            p = rng.choice([('G','C'),('C','G'),('A','U'),('U','A')])
            seq[i]=p[0]
            seq[j]=p[1]
    return seq

def run_one(seed):
    rng = random.Random(seed)
    seq = init_seq(rng)
    d, mfe, en = energy_obj(seq)
    T = 2.0
    best_d = d
    best_seq = seq[:]
    for step in range(6000):
        i = rng.randrange(n)
        if target[i]=='.':
            old = seq[i]
            seq[i]=rng.choice(bases)
            nd, nmfe, nen = energy_obj(seq)
            if nd <= d or rng.random() < math.exp(-(nd-d)/max(T,0.01)):
                d, mfe, en = nd, nmfe, nen
            else:
                seq[i]=old
        else:
            j = target_pairs[i]
            oldi, oldj = seq[i], seq[j]
            p = rng.choice([('G','C'),('C','G'),('A','U'),('U','A'),('G','U'),('U','G')])
            seq[i], seq[j] = p
            nd, nmfe, nen = energy_obj(seq)
            if nd <= d or rng.random() < math.exp(-(nd-d)/max(T,0.01)):
                d, mfe, en = nd, nmfe, nen
            else:
                seq[i], seq[j] = oldi, oldj
        T *= 0.9993
        if d < best_d:
            best_d = d
            best_seq = seq[:]
        if best_d==0:
            break
    return best_d, ''.join(best_seq)

if __name__ == '__main__':
    n_workers = int(sys.argv[1]) if len(sys.argv)>1 else 64
    seeds = list(range(n_workers))
    with Pool(n_workers) as pool:
        results = pool.map(run_one, seeds)
    results.sort(key=lambda x: x[0])
    for d, s in results[:10]:
        print(d, s)
    best = results[0]
    with open('/tmp/sa3_best.txt','w') as f:
        f.write(f"{best[0]}\n{best[1]}\n")
